module asyn_fifo #(
    parameter	WIDTH = 8,
    parameter 	DEPTH = 16,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);


reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];
reg [($clog2(DEPTH))-1:0] waddr_bin, raddr_bin;
reg [($clog2(DEPTH))-1:0] wptr, rptr;
reg [($clog2(DEPTH))-1:0] wptr_buff, rptr_buff;
reg [($clog2(DEPTH))-1:0] wptr_syn, rptr_syn;
wire wen, ren;
wire [($clog2(DEPTH))-1:0] waddr, raddr;

assign wen = winc && !wfull;
assign ren = rinc && !rempty;
assign waddr = waddr_bin[($clog2(DEPTH))-1:0];
assign raddr = raddr_bin[($clog2(DEPTH))-1:0];

always@(posedge wclk or negedge wrstn) begin
    if(!wrstn) begin
        waddr_bin <= 0;
    end else if(winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
    end
end
always@(posedge rclk or negedge rrstn) begin
    if(!rrstn) begin
        raddr_bin <= 0;
    end else if(rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
    end
end

assign wptr[3] = waddr_bin[3] ^ waddr_bin[2];
assign wptr[2] = waddr_bin[2] ^ waddr_bin[1];
assign wptr[1] = waddr_bin[1] ^ waddr_bin[0];
assign wptr[0] = waddr_bin[0] ^ 1'b0;

assign rptr[3] = raddr_bin[3] ^ raddr_bin[2];
assign rptr[2] = raddr_bin[2] ^ raddr_bin[1];
assign rptr[1] = raddr_bin[1] ^ raddr_bin[0];
assign rptr[0] = raddr_bin[0] ^ 1'b0;

always@(posedge wclk or negedge wrstn) begin
    if(!wrstn) begin
        wptr_buff <= 0;
    end else begin
        wptr_buff <= wptr;
    end
end
always@(posedge rclk or negedge rrstn) begin
    if(!rrstn) begin
        rptr_buff <= 0;
    end else begin
        rptr_buff <= rptr;
    end
end

assign wfull = (wptr == {~rptr_syn[($clog2(DEPTH))-1:($clog2(DEPTH))-2], rptr_syn[($clog2(DEPTH))-3:0]});
assign rempty = (rptr == wptr_syn);

always@(posedge rclk or negedge rrstn) begin
    if(!rrstn) begin
        wptr_syn <= 0;
    end else begin
        wptr_syn <= wptr_buff;
    end
end

always@(posedge wclk or negedge wrstn) begin
    if(!wrstn) begin
        rptr_syn <= 0;
    end else begin
        rptr_syn <= rptr_buff;
    end
end

assign rdata = RAM_MEM[raddr];
always@(posedge wclk) begin
    if(wen) begin
        RAM_MEM[waddr] <= wdata;
    end
end
endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
